const items = $input.all();
const processed = [];
const candidateItems = $('Normalize Data & Split Items').all();

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const candidate = candidateItems[i]?.json || {};

  let aiRes = {};
  try {
    let rawText = item.json.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
    rawText = rawText.replace(/^```json\s*/i, '').replace(/\s*```$/i, '').trim();
    aiRes = JSON.parse(rawText);
  } catch (err) {
    aiRes = {
      is_potential_client: false,
      intent_type: 'IRRELEVANT',
      is_provider: false,
      is_fulltime_job: false,
      need: 'Unknown',
      urgency: 'UNKNOWN',
      budget_signal: false,
      qualification_reason: 'JSON parse error from Gemini AI: ' + err.message
    };
  }

  processed.push({
    json: {
      ...candidate,
      is_potential_client: Boolean(aiRes.is_potential_client),
      intent_type: aiRes.intent_type || 'IRRELEVANT',
      is_provider: Boolean(aiRes.is_provider),
      is_fulltime_job: Boolean(aiRes.is_fulltime_job),
      need: aiRes.need || '',
      urgency: aiRes.urgency || 'UNKNOWN',
      budget_signal: Boolean(aiRes.budget_signal),
      qualification_reason: aiRes.qualification_reason || ''
    }
  });
}

return processed;
